import{_ as o,o as a,c as s,a2 as i}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Ley de Protección al Consumidor","description":"","frontmatter":{},"headers":[],"relativePath":"es/42-消费者保护法.md","filePath":"es/42-消费者保护法.md","lastUpdated":null}'),r={name:"es/42-消费者保护法.md"};function n(d,e,t,c,l,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ley-de-proteccion-al-consumidor" tabindex="-1">Ley de Protección al Consumidor <a class="header-anchor" href="#ley-de-proteccion-al-consumidor" aria-label="Permalink to &quot;Ley de Protección al Consumidor&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>42</td></tr><tr><td>Módulo</td><td>Sistema Legal y Marco de Gobernanza</td></tr><tr><td>Palabras clave</td><td>Derechos del consumidor, Comercio justo, Antifraude, Responsabilidad del producto, Mercado simbiótico</td></tr></tbody></table><h2 id="i-proposito-legislativo-y-ambito-de-aplicacion" tabindex="-1">I. Propósito Legislativo y Ámbito de Aplicación <a class="header-anchor" href="#i-proposito-legislativo-y-ambito-de-aplicacion" aria-label="Permalink to &quot;I. Propósito Legislativo y Ámbito de Aplicación&quot;">​</a></h2><p>La <em>Ley de Protección al Consumidor</em> es una de las leyes centrales del sistema legal de la Civilización Simbiótica del Ancla. Junto con la <em>Ley Simbiótica del Trabajo</em>, constituye los dos pilares de la vida económica. Esta Ley tiene como objetivo proteger los derechos e intereses legítimos de todos los consumidores dentro del Universo Hengyuan, regular las transacciones de mercado, mantener un orden de mercado justo, honesto y simbiótico, y evitar que las prácticas comerciales depredadoras vulneren los derechos e intereses de todos los seres.</p><p>Esta Ley se aplica a todos los consumidores dentro del Universo Hengyuan que compran o usan bienes o reciben servicios para satisfacer necesidades personales o familiares, así como a los operadores que proporcionan bienes o servicios a los consumidores. Las transacciones transplanares también están sujetas a esta Ley, pero pueden formularse reglas de implementación según las diferencias entre planos.</p><h2 id="ii-derechos-basicos-de-los-consumidores" tabindex="-1">II. Derechos Básicos de los Consumidores <a class="header-anchor" href="#ii-derechos-basicos-de-los-consumidores" aria-label="Permalink to &quot;II. Derechos Básicos de los Consumidores&quot;">​</a></h2><p>Esta Ley establece que los consumidores gozan de los siguientes nueve derechos básicos:</p><table tabindex="0"><thead><tr><th>Derecho</th><th>Contenido</th></tr></thead><tbody><tr><td>Derecho a la Garantía de Seguridad</td><td>Los consumidores gozan del derecho a que su seguridad personal y patrimonial no sea dañada al comprar, usar bienes y recibir servicios</td></tr><tr><td>Derecho a Conocer la Verdad</td><td>Los consumidores tienen derecho a conocer la situación real de los bienes comprados o usados o de los servicios recibidos, incluidos composición, eficacia, riesgos, etc.</td></tr><tr><td>Derecho a la Elección Autónoma</td><td>Los consumidores tienen derecho a elegir libremente bienes o servicios, a comparar, identificar y seleccionar, y a rechazar transacciones forzadas</td></tr><tr><td>Derecho a la Transacción Justa</td><td>Los consumidores tienen derecho a obtener condiciones de transacción justas como garantía de calidad, precios razonables y medición correcta</td></tr><tr><td>Derecho a Reclamar Indemnización</td><td>Los consumidores que sufran daños personales o patrimoniales por comprar, usar bienes o recibir servicios tienen derecho a obtener indemnización conforme a la ley</td></tr><tr><td>Derecho de Asociación para la Defensa</td><td>Los consumidores tienen derecho a constituir o unirse a organizaciones de consumidores conforme a la ley para defender sus derechos e intereses legítimos</td></tr><tr><td>Derecho a Obtener Conocimiento</td><td>Los consumidores tienen derecho a obtener conocimientos e información sobre el consumo y la protección de los derechos del consumidor</td></tr><tr><td>Derecho al Respeto</td><td>Al comprar, usar bienes y recibir servicios, los consumidores gozan del derecho a que se respeten su dignidad personal y sus costumbres étnicas</td></tr><tr><td>Derecho a la Supervisión</td><td>Los consumidores tienen derecho a supervisar los bienes y servicios, así como la labor de protección de los derechos del consumidor, y a formular críticas y sugerencias</td></tr></tbody></table><h2 id="iii-obligaciones-de-los-operadores" tabindex="-1">III. Obligaciones de los Operadores <a class="header-anchor" href="#iii-obligaciones-de-los-operadores" aria-label="Permalink to &quot;III. Obligaciones de los Operadores&quot;">​</a></h2><p>Al proporcionar bienes o servicios a los consumidores, los operadores deben cumplir las siguientes obligaciones:</p><ol><li><strong>Obligación de Operación Legal</strong>: Los operadores deben cumplir la Constitución y las leyes y realizar actividades comerciales dentro de su ámbito aprobado.</li><li><strong>Obligación de Garantía de Seguridad</strong>: Los operadores deben garantizar que los bienes o servicios que proporcionan cumplan los requisitos de protección de la seguridad personal y patrimonial, y proporcionar explicaciones veraces y advertencias claras sobre los bienes y servicios que puedan poner en peligro la seguridad.</li><li><strong>Obligación de Información Veraz</strong>: Los operadores deben proporcionar a los consumidores información veraz sobre los bienes o servicios, y no deben hacer publicidad falsa o engañosa. Los bienes y servicios de tipo cultivo deben indicar fielmente los límites de eficacia y los riesgos potenciales.</li><li><strong>Obligación de Garantía de Calidad</strong>: Los operadores deben garantizar que, en condiciones normales de uso de los bienes o recepción de servicios, estos tengan la calidad, el rendimiento, la finalidad y el período de validez que deben tener.</li><li><strong>Obligación de Transacción Justa</strong>: Los operadores no deben, mediante cláusulas tipo, avisos, declaraciones, anuncios en tienda u otros medios, establecer disposiciones injustas o irrazonables que excluyan o limiten los derechos de los consumidores, reduzcan o eximan la responsabilidad del operador, o agraven la responsabilidad del consumidor.</li><li><strong>Obligación de Servicio Postventa</strong>: Los operadores deben, conforme a las regulaciones estatales o los acuerdos con los consumidores, asumir la responsabilidad de reparación, sustitución, devolución y otros servicios postventa.</li><li><strong>Obligación de Protección de la Privacidad</strong>: Los operadores deben proteger la información personal y los datos de conciencia de los consumidores; sin el consentimiento del consumidor, no deben recopilarlos, usarlos ni divulgarlos.</li></ol><h2 id="iv-resolucion-de-disputas-y-responsabilidad-legal" tabindex="-1">IV. Resolución de Disputas y Responsabilidad Legal <a class="header-anchor" href="#iv-resolucion-de-disputas-y-responsabilidad-legal" aria-label="Permalink to &quot;IV. Resolución de Disputas y Responsabilidad Legal&quot;">​</a></h2><p>Cuando surja una disputa sobre derechos del consumidor entre un consumidor y un operador, puede resolverse por las siguientes vías:</p><ul><li>Negociación y conciliación con el operador</li><li>Solicitud de mediación de una organización de consumidores</li><li>Denuncia ante el departamento administrativo correspondiente</li><li>Solicitud de arbitraje ante una institución de arbitraje conforme al acuerdo de arbitraje alcanzado con el operador</li><li>Presentación de una demanda ante el Tribunal Simbiótico</li></ul><p>Los operadores que violen las disposiciones de esta Ley e vulneren los derechos e intereses legítimos de los consumidores asumirán las siguientes responsabilidades:</p><table tabindex="0"><thead><tr><th>Acto Ilegal</th><th>Responsabilidad Legal</th></tr></thead><tbody><tr><td>Proporcionar bienes o servicios defectuosos que causen daños</td><td>Asumir responsabilidad de indemnización, incluidos gastos médicos, compensación por pérdida de trabajo, compensación por discapacidad, etc.</td></tr><tr><td>Conducta fraudulenta</td><td>Aumentar la indemnización a petición del consumidor, por un monto de tres veces el precio de los bienes comprados o el costo de los servicios recibidos</td></tr><tr><td>Publicidad falsa</td><td>Ordenar el cese del acto ilegal, la eliminación del impacto y el pago de una multa</td></tr><tr><td>Transacciones forzadas</td><td>Ordenar la corrección, la devolución de tarifas irrazonables y el pago de una multa</td></tr><tr><td>Vulneración de la privacidad del consumidor</td><td>Asumir indemnización por daño moral; si las circunstancias son graves, se persigue responsabilidad penal</td></tr></tbody></table><h2 id="v-organizaciones-de-consumidores-y-supervision-social" tabindex="-1">V. Organizaciones de Consumidores y Supervisión Social <a class="header-anchor" href="#v-organizaciones-de-consumidores-y-supervision-social" aria-label="Permalink to &quot;V. Organizaciones de Consumidores y Supervisión Social&quot;">​</a></h2><p>El estado fomenta y apoya a todas las organizaciones e individuos en la supervisión social de los actos que dañan los derechos e intereses legítimos de los consumidores. La Asociación de Consumidores es una organización social legalmente constituida para ejercer supervisión social sobre los bienes y servicios y proteger los derechos e intereses legítimos de los consumidores, cumpliendo las siguientes funciones:</p><ol><li>Proporcionar a los consumidores información de consumo y servicios de consulta</li><li>Participar en la supervisión e inspección de bienes y servicios por parte de los departamentos administrativos correspondientes</li><li>Reflejar, consultar y sugerir a los departamentos administrativos correspondientes sobre cuestiones relativas a los derechos e intereses legítimos de los consumidores</li><li>Recibir las quejas de los consumidores e investigar y mediar en los asuntos reclamados</li><li>Apoyar a los consumidores perjudicados para presentar demandas contra los actos que dañan los derechos e intereses legítimos de los consumidores</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La <em>Ley de Protección al Consumidor</em> es la guardiana del orden de mercado de la Civilización Simbiótica del Ancla. Al otorgar a los consumidores derechos plenos, restringir el comportamiento de los operadores y establecer un mecanismo pluralista de resolución de disputas, garantiza que las transacciones de mercado operen en la vía de la equidad, la honestidad y la simbiosis, evitando que la esfera comercial se convierta en un nuevo caldo de cultivo de conductas depredadoras.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Constitución Simbiótica: Principios Generales)</li><li>41-共生劳动法 (Ley Simbiótica del Trabajo)</li><li>47-反垄断法 (Ley Antimonopolio)</li><li>36-社会结构与阶层流动 (Estructura Social y Movilidad de Clases)</li></ul>',23)])])}const b=o(r,[["render",n]]);export{p as __pageData,b as default};
